import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the versioned corpus generated by `color_matching`.
///
/// Keep the fixture byte-for-byte aligned with
/// `viamin/color_matching/priv/parity/v1/corpus.json`; the README documents the
/// refresh command for maintainers.
final class WeightedSquaredErrorParityTests: XCTestCase {
    func testVersionOneCorpusMatchesScoresExclusionsAndSelections() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.selection, "earliest-index-wins")

        for scenario in corpus.scenarios {
            try assertParity(for: scenario)
        }
    }

    private func assertParity(for scenario: ParityScenario) throws {
        let scorer = WeightedSquaredErrorScorer()
        let target = TargetResponseVector(channels: scenario.target.channels)
        let weights = ChannelWeights(channels: scenario.weights)
        let palette = try scenario.palette.map(makePaletteColor)
        let actualScores = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }

        XCTAssertEqual(actualScores.count, scenario.expected.scores.count, scenario.id)
        for (actual, expected) in zip(actualScores, scenario.expected.scores) {
            switch (actual, expected.score) {
            case (.excluded, .excluded):
                break
            case (.score(let actual), .value(let expected)):
                XCTAssertEqual(actual, expected, accuracy: 0, scenario.id)
            default:
                XCTFail("\(scenario.id): expected \(expected.score), got \(actual)")
            }
        }

        guard target.hasValues(for: weights) else {
            XCTAssertNil(scenario.expected.selectedIndex, scenario.id)
            return
        }

        let result = try CompositionSolver().solve(
            palette: palette,
            sourceGrids: target.sourceGrids(for: weights),
            weights: weights
        )
        XCTAssertEqual(result.colorIndices, [scenario.expected.selectedIndex], scenario.id)

        if let expectedError = scenario.expected.error {
            let actualError = try XCTUnwrap(result.errors.first, scenario.id)
            XCTAssertEqual(actualError, expectedError, accuracy: 0, scenario.id)
        } else {
            XCTAssertEqual(result.errors, [.infinity], scenario.id)
        }

        if scenario.expected.tieBroke == true {
            let selected = try XCTUnwrap(scenario.expected.selectedIndex, scenario.id)
            XCTAssertEqual(selected, scenario.expected.tiedIndices.min(), scenario.id)
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let fixture = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/weighted_squared_error_v1.json")
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: fixture))
    }

    private func makePaletteColor(_ vector: ParityVector) throws -> PaletteColor {
        let rgb = try XCTUnwrap(RGBColor(hex: vector.hexColor), "Invalid fixture hex: \(vector.hexColor)")
        return PaletteColor(
            id: try XCTUnwrap(vector.index, "Palette fixture is missing an index"),
            hex: vector.hexColor,
            rgb: rgb,
            responses: vector.channels.reduce(into: [:]) { responses, channel in
                guard let condition = LightingCondition(parityName: channel.key) else { return }
                responses[condition] = IlluminationResponse(brightness: channel.value)
            }
        )
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let selection: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let palette: [ParityVector]
    let target: ParityVector
    let weights: [String: Double]
    let expected: ParityExpectation
}

private struct ParityVector: Decodable {
    let channels: [String: Double]
    let hexColor: String
    let index: Int?
}

private struct ParityExpectation: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue
}

private enum ParityScoreValue: Decodable, CustomStringConvertible {
    case excluded
    case value(Double)

    var description: String {
        switch self {
        case .excluded: return "excluded"
        case .value(let value): return String(value)
        }
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected score or excluded")
        }
    }
}

private extension TargetResponseVector {
    init(channels: [String: Double]) {
        self.init(channels.reduce(into: [:]) { responses, channel in
            guard let condition = LightingCondition(parityName: channel.key) else { return }
            responses[condition] = channel.value
        })
    }

    func hasValues(for weights: ChannelWeights) -> Bool {
        weights.activeEntries.allSatisfy { value(for: $0.condition) != nil }
    }

    func sourceGrids(for weights: ChannelWeights) -> [LightingCondition: BrightnessGrid] {
        Dictionary(uniqueKeysWithValues: weights.activeEntries.compactMap { entry in
            value(for: entry.condition).map { (entry.condition, BrightnessGrid(width: 1, height: 1, values: [$0])) }
        })
    }
}

private extension ChannelWeights {
    init(channels: [String: Double]) {
        self.init(
            white: channels["white"] ?? 0,
            red: channels["red"] ?? 0,
            green: channels["green"] ?? 0,
            blue: channels["blue"] ?? 0,
            lps: channels["lps"] ?? 0
        )
    }
}

private extension LightingCondition {
    init?(parityName: String) {
        switch parityName {
        case "white": self = .white
        case "red": self = .red
        case "green": self = .green
        case "blue": self = .blue
        case "lps": self = .lps
        default: return nil
        }
    }
}
